// 9. NAVEGACIÓN DE LA BARRA STICKY Y MODAL VISOR DE PDF INTEGRADO
// ============================================================================
function switchTopNav(target) {
  const btns = ["navBtnU6", "navBtnU7", "navBtnU8", "navBtnEj", "navBtnParcial"];
  btns.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.classList.remove("active");
  });

  if (target === "u6" || target === "u7" || target === "u8") {
    currentUnit = target;
    currentVideoIndex = 0;
    currentConceptId = "all";
    const activeBtn = document.getElementById("navBtn" + target.toUpperCase());
    if (activeBtn) activeBtn.classList.add("active");
    renderVideoBars();
    renderVideoConceptsBox();
    initOrUpdateYouTubeEmbed(null);
    renderConceptPillsAndDevelopment();
    window.scrollTo({ top: 0, behavior: "smooth" });
  } else if (target === "ejercicios") {
    const activeBtn = document.getElementById("navBtnEj");
    if (activeBtn) activeBtn.classList.add("active");
    setBottomMode("guided");
    const sec = document.getElementById("bottomExercisesSection");
    if (sec) sec.scrollIntoView({ behavior: "smooth", block: "start" });
  } else if (target === "parcial") {
    const activeBtn = document.getElementById("navBtnParcial");
    if (activeBtn) activeBtn.classList.add("active");
    setBottomMode("simulacro");
    const sec = document.getElementById("bottomExercisesSection");
    if (sec) sec.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

let modalDocId = "u6";
let modalPageNum = 1;

function openPdfModal(docId = "u6", pageNum = 1) {
  modalDocId = PDF_BUNDLE.docs[docId] ? docId : "u6";
  const docObj = PDF_BUNDLE.docs[modalDocId];
  modalPageNum = Math.max(1, Math.min(pageNum || 1, docObj.numPages));

  const modal = document.getElementById("pdfModalOverlay");
  if (modal) {
    modal.classList.remove("hidden");
    renderPdfModalContent();
  }
}

function closePdfModal() {
  const modal = document.getElementById("pdfModalOverlay");
  if (modal) modal.classList.add("hidden");
}

function changeModalPdfDoc(docId) {
  openPdfModal(docId, 1);
}

function changeModalPdfPage(delta) {
  const docObj = PDF_BUNDLE.docs[modalDocId];
  if (!docObj) return;
  const next = modalPageNum + delta;
  if (next >= 1 && next <= docObj.numPages) {
    modalPageNum = next;
    renderPdfModalContent();
  }
}

function jumpModalPdfPage(pNum) {
  const docObj = PDF_BUNDLE.docs[modalDocId];
  if (!docObj) return;
  modalPageNum = Math.max(1, Math.min(parseInt(pNum, 10) || 1, docObj.numPages));
  renderPdfModalContent();
}

function renderPdfModalContent() {
  const docObj = PDF_BUNDLE.docs[modalDocId];
  if (!docObj) return;

  const docSel = document.getElementById("modalDocSelect");
  if (docSel && docSel.value !== modalDocId) docSel.value = modalDocId;

  const pageSel = document.getElementById("modalPageSelect");
  if (pageSel) {
    pageSel.innerHTML = docObj.pages.map(p =>
      `<option value="${p.page}" ${p.page === modalPageNum ? 'selected' : ''}>Página ${p.page} de ${docObj.numPages}</option>`
    ).join("");
  }

  const pageObj = docObj.pages[modalPageNum - 1] || docObj.pages[0];
  const bodyEl = document.getElementById("modalPdfPageBody");
  if (!bodyEl) return;

  const figsHtml = (pageObj.figs || []).map(fKey => {
    const src = PDF_BUNDLE.figures[fKey];
    if (!src) return "";
    return `<div class="my-3 flex justify-center"><img src="${src}" alt="Figura PDF" class="max-w-full h-auto rounded-xl shadow-md max-h-72 bg-white p-1.5"></div>`;
  }).join("");

  const cleanLines = pageObj.text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

  bodyEl.innerHTML = `
    <div class="p-5 rounded-2xl bg-slate-900/90 text-slate-100 space-y-2.5 max-w-3xl mx-auto text-center">
      <div class="text-xs uppercase tracking-wider text-amber-300 font-tier-3">
        ${docObj.title} • Página ${pageObj.page} de ${docObj.numPages}
      </div>
      <div class="space-y-2 text-sm md:text-base leading-relaxed font-tier-5">
        ${cleanLines.map(line => `<p>${line.replace(/</g, "&lt;")}</p>`).join("")}
      </div>
      ${figsHtml}
    </div>
  `;
}

window.addEventListener("DOMContentLoaded", () => {
  loadSavedTimes();
  renderVideoBars();
  renderVideoConceptsBox();
  initOrUpdateYouTubeEmbed(null);
  startFallbackProgressTimer();
  renderConceptPillsAndDevelopment();
  renderBottomBoxes();
});
